/*List widget*/

.edhub-list {
    margin: 0;
    padding: 0;
    list-style-type: none;
}

.edhub-list li {
    position: relative;
    margin-bottom: 10px;
}

.edhub-list.style_1 li:before {
    content: "";
    height: 12px;
    width: 9px;
    background-color: var(--color_primary);
    position: absolute;
    top: 8px;
    left: 0;
    -webkit-transition: all 0.3s ease-in-out;
    transition: all 0.3s ease-in-out;
}

.edhub-list.style_1 li:after {
    content: "";
    height: 12px;
    width: 9px;
    background-color: #bebfc1;
    position: absolute;
    top: 9px;
    left: 1px;
    -webkit-transition: all 0.3s ease-in-out;
    transition: all 0.3s ease-in-out;
}

.edhub-list.style_1 li a {
    position: relative;
    margin-left: 22px;
}

.edhub-list li a:after {
    content: "";
    height: 1px;
    width: 0;
    background-color: #fff;
    position: absolute;
    right: 0;
    bottom: 0;
    -webkit-transition: all 0.3s ease-in-out;
    transition: all 0.3s ease-in-out;
}

.edhub-list li:hover a:after {
    width: 100%;
}

.edhub-list.style_1 li:hover:after {
    background-color: var(--color_primary);
}

.edhub-list.style_1 li:hover:before {
    background-color: #bebfc1;
}

.edhub-list.style_2 li:before {
    display: inline-block;
    content: "\f067";
    font-family: "Font Awesome 5 Free";
    font-weight: 600;
    font-size: 13px;
    color: #6b6b6b;
    -webkit-transition: all 0.3s ease-in-out;
    transition: all 0.3s ease-in-out;
}

.edhub-list.style_2 li a {
    position: relative;
    z-index: 1;
    margin-left: 15px;
}

.edhub-list.style_2 li:hover:before {
    -webkit-transform: rotate(180deg);
    -ms-transform: rotate(180deg);
    transform: rotate(180deg);
    color: var(--color_primary);
}

.edhub-list li:last-child {
    margin-bottom: 0;
}

