}
.leftDiv img:hover{
    box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
    border-radius: 10px;
}

figure {
    margin: 1em 0;
    /* Extra wide images within figure tags don't overflow the content area. */
}

table {
    border-collapse: collapse;
    border-spacing: 0;
    margin: 15px 0;
    width: 100%;
}

table th,
table td {
    border: 1px solid #ebebeb;
    padding: 5px;
    text-align: center;
}

/*--------------------------------------------------------------
# Forms
--------------------------------------------------------------*/
button,
input[type="button"],
input[type="reset"],
input[type="submit"] {
    background-color: #14133b;
    border: medium none;
    color: #fff;
    padding: 2px 15px;
}

button:hover,
input[type="button"]:hover,
input[type="reset"]:hover,
