.tutor-certificate-template input[type='radio']:checked+.tutor-certificate-template-inner::after {
    opacity: 1
}

.tutor-certificate-template-icon {
    position: absolute;
    right: -12px;
    top: -20px;
    z-index: 10;
    opacity: 0;
