.tutor-passowrd-strength-hint {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 7px
}

.tutor-passowrd-strength-hint .indicator {
    height: 10px;
    margin: 10px 0;
    gap: 25px;
    align-items: center;
    justify-content: space-between;
    display: none
}

.tutor-passowrd-strength-hint .indicator span {
    position: relative;
    height: 2px;
    width: 72px;
    background: lightgrey;
    border-radius: 5px
}

.tutor-passowrd-strength-hint .indicator span.active:before {
    position: absolute;
    content: '';
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;
    border-radius: 5px
}

.tutor-passowrd-strength-hint .indicator span.weak:before {
    background-color: #F44337
}

.tutor-passowrd-strength-hint .indicator span.medium:before {
    background-color: #ED9700
}

.tutor-passowrd-strength-hint .indicator span.strong:before {
    background-color: var(--tutor-color-success)
}

.tutor-passowrd-strength-hint .indicator span:nth-child(2) {
    margin: 0 3px
}

.tutor-passowrd-strength-hint .text {
    display: none;
    text-align: right;
    text-transform: capitalize
}

.tutor-passowrd-strength-hint .text.weak {
    color: #F44337
}

.tutor-passowrd-strength-hint .text.medium {
    color: #ED9700
}

.tutor-passowrd-strength-hint .text.strong {
    color: var(--tutor-color-success)
}

.tutor-card {
    background-color: #FFFFFF;
    border: 1px solid var(--tutor-border-color);
    position: relative;
    border-radius: 6px;
    display: flex;
    flex-direction: column;
    min-width: 0;
    word-wrap: break-word
}

.tutor-card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid var(--tutor-border-color);
    padding: 16px 20px;
    border-radius: 5px 5px 0 0
}

.tutor-card-title {
    font-size: 16px;
    font-weight: 500;
    margin: 0
}

.tutor-card-body {
    flex: 1 1 auto;
    padding: 20px
}

.tutor-card-footer {
    padding: 16px 20px;
    border-radius: 0 0 5px 5px
}

.tutor-card-footer:not(.tutor-no-border) {
    border-top: 1px solid var(--tutor-border-color)
}

.tutor-card-image {
    border-radius: 5px
}

.tutor-card-image-top {
    border-radius: 5px 5px 0px 0px
}

.tutor-card-image-right {
    border-radius: 0px 5px 5px 0px
}

.tutor-card-image-bottom {
    border-radius: 0px 0px 5px 5px
}

.tutor-card-image-left {
    border-radius: 5px 0px 0px 5px
}

.tutor-card-secondary {
    border: 2px solid #E0E2EA
}

.tutor-card.is-selected {
    background-color: rgba(var(--tutor-color-primary-rgb), 0.05);
    border-color: rgba(var(--tutor-color-primary-rgb), 0.4)
}

.tutor-card.is-active {
    background-color: rgba(var(--tutor-color-primary-rgb), 0.05);
    border-color: var(--tutor-color-primary)
}

.tutor-card-sm .tutor-card-header,.tutor-card-sm .tutor-card-body,.tutor-card-sm .tutor-card-footer {
    padding: 16px
}

.tutor-card-md .tutor-card-header {
    padding: 24px 32px
}

.tutor-card-md .tutor-card-body {
    padding: 32px
}

.tutor-card-md .tutor-card-footer {
    padding: 24px 32px
}

.tutor-card-list {
    display: flex;
    flex-direction: column;
    padding-left: 0;
    margin-bottom: 0;
    border-radius: 6px
}

.tutor-card-list:first-child {
    border-top-width: 0;
    border-top-left-radius: 5px;
    border-top-right-radius: 5px
}

.tutor-card-list-item {
    position: relative;
    display: block;
    color: var(--tutor-body-color);
    text-decoration: none;
    background-color: #fff
}

.tutor-card-list-item:nth-child(even) {
    background-color: #fcfcfd
}

.tutor-card-list-item:not(:last-child) {
    border-bottom: 1px solid #CDCFD5
}

.tutor-card-list-item:first-child {
    border-top-left-radius: 6px;
    border-top-right-radius: 6px
}

.tutor-card-list-item:last-child {
    border-bottom-left-radius: 6px;
    border-bottom-right-radius: 6px
}

@media (min-width: 1200px) {
    .tutor-card-list-horizontal {
        flex-direction:row
    }

    .tutor-card-list-horizontal .tutor-card-list-item {
        flex-shrink: 0;
        flex-grow: 1;
        border-bottom: 0;
        border-radius: 6px
    }

    .tutor-card-list-horizontal .tutor-card-list-item:not(:last-child) {
        border-right: 1px solid #CDCFD5;
        border-top-right-radius: 0;
        border-bottom-right-radius: 0
    }
}

.tutor-accordion-item {
    background-color: #fff;
    border: 1px solid #E0E2EA;
    border-radius: 6px
}

.tutor-accordion-item:not(:last-child) {
    margin-bottom: 10px
}

@media (min-width: 992px) {
    .tutor-accordion-item:not(:last-child) {
        margin-bottom:20px
    }
}

.tutor-accordion-item-header {
    position: relative;
    font-size: 20px;
    font-weight: 500;
    line-height: 1.4;
    padding: 16px 40px 16px 20px;
    margin: 0 !important;
    transition: 200ms;
    background-color: #FCFCFD;
    color: var(--tutor-color-secondary);
    user-select: none;
    border-radius: 6px;
    transition: 300ms ease-in;
    cursor: pointer
}

.tutor-accordion-item-header::after {
    content: '\e940';
    font-family: 'tutor' !important;
    color: var(--tutor-color-primary);
    font-size: 16px;
    font-weight: normal;
    position: absolute;
    right: 16px;
    top: 50%;
    transform: translateY(-50%) rotate(0deg);
    transition: 150ms
}

.tutor-accordion-item-header:hover {
    color: var(--tutor-color-primary)
}

.tutor-accordion-item-header.is-active {
    color: var(--tutor-color-primary);
    background-color: #eff1f6;
    border-radius: 6px 6px 0 0
}

.tutor-accordion-item-header.is-active::after {
    transform: translateY(-50%) rotate(-90deg)
}

.tutor-accordion-item-header .tooltip-wrap.tooltip-icon {
    position: relative;
    font-size: 16px;
    top: 1px;
    margin-left: 8px
}

.tutor-accordion-item-body {
    overflow: hidden
}

.tutor-accordion-item-body-content {
    padding: 0 16px;
    border-top: 1px solid #E0E2EA
}

.tutor-modal {
    position: fixed;
    top: 0;
    left: 0;
    display: none;
    width: 100%;
    height: 100%;
    overflow-x: hidden;
    overflow-y: auto;
    outline: 0;
    z-index: 99999
}

.tutor-modal-open {
    overflow: hidden
}

.tutor-modal.tutor-is-active,.tutor-modal-active {
    display: block
}

.tutor-modal-overlay {
    position: fixed;
    height: 100%;
    width: 100%;
    top: 0;
    left: 0;
    background-color: rgba(0,0,0,0.75);
    z-index: -1
}

.tutor-modal-window {
    position: relative;
    width: auto;
    pointer-events: none;
    display: flex;
    align-items: center;
    max-width: 640px;
    margin: 48px auto;
    min-height: calc(100% - 96px)
}

.tutor-modal-window-lg {
    max-width: 880px
}

.tutor-modal-window-md {
    max-width: 520px
}

.tutor-modal-window-sm {
    max-width: 430px
}

.tutor-modal-content {
    position: relative;
    display: flex;
    flex-direction: column;
    width: 100%;
    pointer-events: auto;
    background-color: #EFF1F7;
    background-clip: padding-box;
    border: 1px solid var(--tutor-border-color);
    border-radius: 16px;
    outline: 0
}

.tutor-modal-content-white {
    background-color: #FFFFFF
}

.tutor-modal-header,.tutor-modal-footer {
    padding: 16px 32px;
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: space-between;
    background-color: #FFFFFF
}

.tutor-modal-header {
    border-bottom: 1px solid var(--tutor-border-color);
    border-top-left-radius: 16px;
    border-top-right-radius: 16px
}

.tutor-modal-header .tutor-modal-close {
    margin-right: -16px
}

.tutor-modal .tutor-modal-close-o {
    position: absolute;
    top: 16px;
    right: 16px;
    font-size: 20px;
    z-index: 1
}

.tutor-modal-title {
    margin: 0;
    font-size: 20px;
    color: var(--tutor-body-color);
    font-weight: 700;
    line-height: 1.2
}

.tutor-modal-footer {
    border-top: 1px solid var(--tutor-border-color);
    border-bottom-right-radius: 16px;
    border-bottom-left-radius: 16px
}

.tutor-modal-body {
    position: relative;
    padding: 24px 32px;
    flex: 1 1 auto
}

.tutor-modal-scrollable .tutor-modal-window {
    height: calc(100% - 96px)
}

