.tutor-nav-tabs .tutor-nav-link.is-active {
    background-color: #FFFFFF;
    border-top-color: var(--tutor-color-primary);
    border-bottom-color: #FFFFFF
}

.tutor-nav-tabs .tutor-nav-item {
    align-items: stretch;
    display: flex;
    flex: 1 1 auto
}

.tutor-nav-tabs .tutor-nav-item:first-child .tutor-nav-link {
    border-radius: 5px 0 0 0
}

.tutor-nav-tabs .tutor-nav-item:last-child .tutor-nav-link {
    border-radius: 0 5px 0 0;
    border-right: 0
}

.tutor-nav-tabs-container {
    background-color: #FFFFFF;
    border: 1px solid var(--tutor-border-color);
    border-radius: 6px
}

.tutor-nav-v {
    flex-direction: column;
    border-bottom: 0
}

.tutor-nav-v .tutor-nav-item {
    margin-right: 0
}

.tutor-nav-v .tutor-nav-item:not(:last-child) {
    margin-bottom: 4px
}

.tutor-nav-admin {
    border-bottom: 0 !important
}

.tutor-nav-admin .tutor-nav-item {
    margin: 0
}

.tutor-nav-admin .tutor-nav-link {
    padding: 20px 16px
}

.tutor-tab-item:not(.is-active) {
    display: none
}

.tutor-widget-title {
    font-size: 20px;
    font-weight: 500;
    color: var(--tutor-body-color);
    margin: 0 0 24px
}

.tutor-list {
    list-style: none;
    padding: 0;
    margin: 0
}

.tutor-list-item {
    position: relative;
    display: block;
    font-size: 16px;
    color: var(--tutor-body-color);
    text-decoration: none
}

.tutor-list-item:not(:last-child) {
    margin-bottom: 16px
}

.tutor-list-item label {
    display: flex;
    align-items: center;
    margin: 0;
    padding: 0;
    cursor: pointer
}

.tutor-list-item label input[type="checkbox"] {
    margin-right: 16px
}

.tutor-progress-bar {
    position: relative;
    width: 100%;
    height: 4px;
    background: #e3e5eb;
    border-radius: 10px;
    overflow: hidden
}

.tutor-progress-value {
    background: var(--tutor-color-primary);
    position: absolute;
    width: var(--tutor-progress-value);
    height: 100%
}

.tutor-progress-circle {
    --w: 24px;
    --pd: 3px;
    position: relative;
    width: var(--w);
    height: var(--w);
    padding: var(--pd);
    border-radius: 50%;
    background: conic-gradient(var(--tutor-color-primary) var(--pro), 0, rgba(var(--tutor-color-primary-rgb), 0.15) 100%)
}

.tutor-progress-circle:before {
    content: '';
    position: absolute !important;
    inset: calc(0% + var(--pd));
    border-radius: 50%;
    background: #fff
}
